import {
  createTheme,
  type PaletteMode,
  type Theme,
  type ThemeOptions,
} from '@mui/material/styles';
import { mergeSx } from 'merge-sx';
import { mergeSvThemeOptions, svColorDefaults } from './defaults';
import { svTokens } from './tokens';

function schemeStyles(
  theme: Theme,
  light: Record<string, string>,
  dark: Record<string, string>
) {
  // A shared CSS variable already follows the active scheme. Repeating it in
  // a dark selector would unnecessarily override consumer sx custom properties.
  const darkOverrides = Object.fromEntries(
    Object.entries(dark).filter(([name, value]) => value !== light[name])
  );
  return { ...light, ...theme.applyStyles('dark', darkOverrides) };
}

export function createSvTheme(options: ThemeOptions = {}): Theme {
  const mode = options.defaultColorScheme ?? options.palette?.mode ?? 'light';
  const paletteOverrides = (scheme: PaletteMode) => {
    if (!options.cssVariables && !options.colorSchemes) return options.palette;
    if (scheme === mode && options.palette) return options.palette;
    const config = options.colorSchemes?.[scheme];
    return config && config !== true ? config.palette : undefined;
  };
  const secondaryColor = (theme: Theme, scheme: PaletteMode) =>
    paletteOverrides(scheme)?.text?.secondary
      ? (theme.vars ?? theme).palette.text.secondary
      : scheme === 'dark'
        ? '#828282'
        : '#8e8e8e';
  const errorColor = (theme: Theme, scheme: PaletteMode) =>
    paletteOverrides(scheme)?.error
      ? (theme.vars ?? theme).palette.error.main
      : '#d64933';
  const buttonSx = (theme: Theme) => {
    const tokens = svTokens(theme);
    const palette = (theme.vars ?? theme).palette;
    const colors = (scheme: PaletteMode) => ({
      '--SvButton-error': errorColor(theme, scheme),
      '--SvButton-errorHover': paletteOverrides(scheme)?.error
        ? palette.error.dark
        : '#de6d5c',
      '--SvButton-success': paletteOverrides(scheme)?.success
        ? palette.success.main
        : tokens.green,
      '--SvButton-successHover': paletteOverrides(scheme)?.success
        ? palette.success.dark
        : (tokens.greenHover ?? '#1fbf4c'),
      '--SvButton-successContrast': paletteOverrides(scheme)?.success
        ? palette.success.contrastText
        : '#fff',
    });
    return schemeStyles(
      theme,
      {
        '--SvButton-primary': tokens.accent,
        '--SvButton-primaryHover': tokens.accentHover,
        '--SvButton-primaryContrast': '#fff',
        '--SvButton-errorContrast': '#fff',
        ...colors('light'),
        '--SvButton-surface': options.sv?.surface ?? 'rgba(20,20,20,0.06)',
        '--SvButton-surfaceHover':
          options.sv?.surfaceHover ?? 'rgba(20,20,20,0.1)',
        '--SvButton-muted': '#8e8e8e',
      },
      {
        ...colors('dark'),
        '--SvButton-surface': options.sv?.surface ?? 'rgba(247,247,247,0.06)',
        '--SvButton-surfaceHover':
          options.sv?.surfaceHover ?? 'rgba(247,247,247,0.1)',
        '--SvButton-muted': '#828282',
      }
    );
  };
  const checkboxSx = (theme: Theme) => ({
    '--SvCheckbox-accent': svTokens(theme).accent,
    '--SvCheckbox-stroke': options.sv?.stroke ?? '#ccc',
    '--SvCheckbox-foreground': '#fff',
    ...theme.applyStyles('dark', {
      '--SvCheckbox-stroke': options.sv?.stroke ?? '#333',
    }),
  });
  const switchSx = (theme: Theme) => ({
    '--SvSwitch-neutral': '#8e8e8e',
    ...theme.applyStyles('dark', { '--SvSwitch-neutral': '#828282' }),
  });
  const sliderSx = (theme: Theme) => ({
    '--SvSlider-default-stroke': options.sv?.stroke ?? '#ccc',
    ...theme.applyStyles('dark', {
      '--SvSlider-default-stroke': options.sv?.stroke ?? '#333',
    }),
  });
  const radioSx = (theme: Theme) => ({
    '--SvRadio-accent': svTokens(theme).accent,
    '--SvRadio-stroke': options.sv?.stroke ?? '#ccc',
    '--SvRadio-foreground': '#fff',
    ...theme.applyStyles('dark', {
      '--SvRadio-stroke': options.sv?.stroke ?? '#333',
    }),
  });
  const fieldSx = (theme: Theme) => {
    return schemeStyles(
      theme,
      {
        '--SvField-accent': svTokens(theme).accent,
        '--SvField-stroke': options.sv?.stroke ?? '#ccc',
        '--SvField-secondary': secondaryColor(theme, 'light'),
        '--SvField-error': errorColor(theme, 'light'),
      },
      {
        '--SvField-error': errorColor(theme, 'dark'),
        '--SvField-stroke': options.sv?.stroke ?? '#333',
        '--SvField-secondary': secondaryColor(theme, 'dark'),
      }
    );
  };
  const chipSx = (theme: Theme) => ({
    '--SvChip-surface': options.sv?.surface ?? 'rgba(20,20,20,0.06)',
    '--SvChip-surface-hover': options.sv?.surfaceHover ?? 'rgba(20,20,20,0.1)',
    '--SvChip-icon-color': secondaryColor(theme, 'light'),
    ...theme.applyStyles('dark', {
      '--SvChip-surface': options.sv?.surface ?? 'rgba(247,247,247,0.06)',
      '--SvChip-surface-hover':
        options.sv?.surfaceHover ?? 'rgba(247,247,247,0.1)',
      '--SvChip-icon-color': secondaryColor(theme, 'dark'),
    }),
  });
  const tagInputSx = (theme: Theme) =>
    schemeStyles(
      theme,
      {
        '--SvTagInput-surface': options.sv?.surface ?? 'rgba(20,20,20,0.06)',
        '--SvTagInput-secondary': secondaryColor(theme, 'light'),
        '--SvTagInput-error': errorColor(theme, 'light'),
      },
      {
        '--SvTagInput-surface': options.sv?.surface ?? 'rgba(247,247,247,0.06)',
        '--SvTagInput-secondary': secondaryColor(theme, 'dark'),
        '--SvTagInput-error': errorColor(theme, 'dark'),
      }
    );
  const selectSx = (theme: Theme) => ({
    '--SvSelect-accent': svTokens(theme).accent,
    '--SvSelect-stroke': options.sv?.stroke ?? '#ccc',
    '--SvSelect-secondary': secondaryColor(theme, 'light'),
    '--SvSelect-error': (theme.vars ?? theme).palette.error.main,
    ...theme.applyStyles('dark', {
      '--SvSelect-stroke': options.sv?.stroke ?? '#333',
      '--SvSelect-secondary': secondaryColor(theme, 'dark'),
    }),
  });
  const menuSx = (theme: Theme) => {
    const palette = (theme.vars ?? theme).palette;
    return {
      '--SvMenu-stroke': options.sv?.stroke ?? palette.divider,
      ...theme.applyStyles('dark', {
        '--SvMenu-surface': paletteOverrides('dark')?.background?.paper
          ? palette.background.paper
          : 'rgba(34,34,34,0.48)',
        '--SvMenu-hover': paletteOverrides('dark')?.action?.hover
          ? palette.action.hover
          : 'rgba(43,43,43,0.64)',
        '--SvMenu-stroke':
          options.sv?.stroke ??
          (paletteOverrides('dark')?.divider ? palette.divider : '#333'),
        '--SvMenu-secondary': secondaryColor(theme, 'dark'),
        '--SvMenu-danger': errorColor(theme, 'dark'),
      }),
    };
  };
  const defaults: ThemeOptions = {
    ...svColorDefaults(mode),
    typography: {
      fontFamily: 'Inter, sans-serif',
      button: { textTransform: 'none', fontWeight: 500 },
    },
    shape: { borderRadius: 8 },
    components: {
      SvChip: { defaultProps: { sx: chipSx } },
      SvMenu: { defaultProps: { sx: menuSx } },
      SvTagInput: { defaultProps: { sx: tagInputSx } },
      SvSelect: { defaultProps: { sx: selectSx } },
      SvField: { defaultProps: { sx: fieldSx } },
      SvIconButton: { defaultProps: { sx: buttonSx } },
      SvCheckbox: { defaultProps: { sx: checkboxSx } },
      SvRadio: { defaultProps: { sx: radioSx } },
      SvSlider: { defaultProps: { sx: sliderSx } },
      SvSwitch: { defaultProps: { sx: switchSx } },
      SvButton: {
        defaultProps: {
          sx: buttonSx,
        },
      },
    },
  };
  return createTheme(
    mergeSvThemeOptions(defaults, {
      ...options,
      components: {
        ...options.components,
        SvChip: {
          defaultProps: {
            ...options.components?.SvChip?.defaultProps,
            sx: mergeSx(chipSx, options.components?.SvChip?.defaultProps?.sx),
          },
        },
        SvMenu: {
          defaultProps: {
            ...options.components?.SvMenu?.defaultProps,
            sx: mergeSx(menuSx, options.components?.SvMenu?.defaultProps?.sx),
          },
        },
        SvTagInput: {
          defaultProps: {
            ...options.components?.SvTagInput?.defaultProps,
            sx: mergeSx(
              tagInputSx,
              options.components?.SvTagInput?.defaultProps?.sx
            ),
          },
        },
        SvSelect: {
          defaultProps: {
            ...options.components?.SvSelect?.defaultProps,
            sx: mergeSx(
              selectSx,
              options.components?.SvSelect?.defaultProps?.sx
            ),
          },
        },
        SvField: {
          defaultProps: {
            ...options.components?.SvField?.defaultProps,
            sx: mergeSx(fieldSx, options.components?.SvField?.defaultProps?.sx),
          },
        },
        SvIconButton: {
          defaultProps: {
            ...options.components?.SvIconButton?.defaultProps,
            sx: mergeSx(
              buttonSx,
              options.components?.SvIconButton?.defaultProps?.sx
            ),
          },
        },
        SvButton: {
          defaultProps: {
            ...options.components?.SvButton?.defaultProps,
            sx: mergeSx(
              defaults.components?.SvButton?.defaultProps?.sx,
              options.components?.SvButton?.defaultProps?.sx
            ),
          },
        },
        SvSwitch: {
          defaultProps: {
            ...options.components?.SvSwitch?.defaultProps,
            sx: mergeSx(
              switchSx,
              options.components?.SvSwitch?.defaultProps?.sx
            ),
          },
        },
        SvSlider: {
          defaultProps: {
            ...options.components?.SvSlider?.defaultProps,
            sx: mergeSx(
              sliderSx,
              options.components?.SvSlider?.defaultProps?.sx
            ),
          },
        },
        SvRadio: {
          defaultProps: {
            ...options.components?.SvRadio?.defaultProps,
            sx: mergeSx(radioSx, options.components?.SvRadio?.defaultProps?.sx),
          },
        },
        SvCheckbox: {
          defaultProps: {
            ...options.components?.SvCheckbox?.defaultProps,
            sx: mergeSx(
              checkboxSx,
              options.components?.SvCheckbox?.defaultProps?.sx
            ),
          },
        },
      },
    } satisfies ThemeOptions)
  );
}
